 @Test public void continuouslyFollowHeldTargets()throws Exception {
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(prepare(54,17354,400,true,false))){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] hud={null};Rect b=new Rect(),hb=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);hud[0]=a.findViewById(R.id.item_overlay);gl[0].getGlobalVisibleRect(b);hud[0].getGlobalVisibleRect(hb);gl[0].camera.focus(800,480);});readyGL(gl[0],4);scene.onActivity(a->{gl[0].camera.focus(800,480);hud[0].noteTargets(new short[]{800,-1,-1,-1,-1},new short[]{480,-1,-1,-1,-1});});long hash=NativeInterface.stateHash();float start=gl[0].camera.left,px=b.left+b.width()*.85f,py=b.top+b.height()*.5f;long down=SystemClock.uptimeMillis();touch(down,0,px,py);JSONArray trace=new JSONArray();double[] maxError={0};
   for(int sample=0;sample<12;sample++){SystemClock.sleep(90);scene.onActivity(a->{try{short[][] xx=(short[][])get(a,"xs"),yy=(short[][])get(a,"ys");int t=StaticBits.team;double error=Math.hypot(b.left+gl[0].camera.screenX(xx[t][0],b.width())-px,b.top+gl[0].camera.screenY(yy[t][0],b.height())-py);maxError[0]=Math.max(maxError[0],error);trace.put(new JSONArray().put(gl[0].camera.left).put(gl[0].camera.bottom).put(xx[t][0]).put(yy[t][0]));}catch(Exception e){throw new RuntimeException(e);}});}
   write("controls177-camera-diagnostic.json",new JSONObject().put("start",start).put("last",gl[0].camera.left).put("touching",gl[0].camera.touching()).put("following",gl[0].camera.following).put("overview",gl[0].camera.overview).put("screen_bounds",b.toString()).put("held_xy",new JSONArray().put(px).put(py)).put("trace",trace));picture("controls177-camera-diagnostic.jpg");Assert.assertTrue("camera moves while held without another MOVE",gl[0].camera.left>start+160);Assert.assertTrue("reprojected marker under same finger "+maxError[0],maxError[0]<3);picture("controls177-held-continuous.jpg");touch(down,2,b.left+b.width()*.2f,py);float turn=gl[0].camera.left;SystemClock.sleep(500);Assert.assertTrue("same gesture reverses camera",gl[0].camera.left<turn-55);touch(down,1,b.left+b.width()*.2f,py);short[][] held=targets(scene);SystemClock.sleep(300);Assert.assertArrayEquals("release holds final world point",held[0],targets(scene)[0]);Assert.assertFalse(gl[0].camera.touching());picture("controls177-release.jpg");
   miniTap(hud[0],hb,400,700,false);SystemClock.sleep(100);float pan=gl[0].camera.left;SystemClock.sleep(150);Assert.assertFalse(gl[0].camera.following);Assert.assertEquals(pan,gl[0].camera.left,.01f);Assert.assertArrayEquals(held[0],targets(scene)[0]);
   scene.onActivity(a->gl[0].camera.focus(800,480));int[] ids={0,3,7,11,19};float[] xx={b.left+b.width()*.75f,b.left+b.width()*.35f,b.left+b.width()*.45f,b.left+b.width()*.55f,b.left+b.width()*.65f},yy={py,py+20,py-20,py+40,py-40};long five=SystemClock.uptimeMillis();for(int k=0;k<5;k++)fingers(five,k==0?0:5|(k<<8),k+1,ids,xx,yy);SystemClock.sleep(250);scene.onActivity(a->{try{short[][] x=(short[][])get(a,"xs"),y=(short[][])get(a,"ys");for(int k=0;k<5;k++){double error=Math.hypot(b.left+gl[0].camera.screenX(x[StaticBits.team][k],b.width())-xx[k],b.top+gl[0].camera.screenY(y[StaticBits.team][k],b.height())-yy[k]);Assert.assertTrue("five targets stay at fingers "+error,error<3);}}catch(Exception e){throw new RuntimeException(e);}});for(int n=5;n>=2;n--)fingers(five,6|((n-1)<<8),n,ids,xx,yy);fingers(five,1,1,ids,xx,yy);Assert.assertFalse(gl[0].camera.touching());Assert.assertEquals(hash,NativeInterface.stateHash());
   write("controls177-continuous.json",new JSONObject().put("status","PASS").put("stationary_hold_without_MOVE",true).put("camera_advanced_cells",trace.getJSONArray(11).getDouble(0)-start).put("max_target_error_px",maxError[0]).put("trace",trace).put("five_pointer_ids",new JSONArray(ids)).put("release_retained",true).put("minimap_no_command",true).put("hash_unchanged_during_ui",true).put("models",0));
  }
 }
 @Test public void naturalDeathAndTwentySecondEffect()throws Exception {
  JSONArray records=new JSONArray();for(int[] fixture:new int[][]{{7,106,3},{6,127,0}}){int kind=fixture[0],seed=fixture[1],team=fixture[2];Intent intent=prepare(1,seed,100,true,false);StaticBits.team=team;
   try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
    frozen(scene);for(int t=0;t<6;t++)NativeInterface.setPlayerPosition(t,IDLE,IDLE);for(int n=0;n<2000&&NativeInterface.itemSnapshot()[2]==0;n++)NativeInterface.stepDots();int[] wave=NativeInterface.itemSnapshot();int slot=-1;for(int k=0;k<com.xenris.liquidwarsos.cloud.SnapshotItems.slots(wave);k++)if(wave[com.xenris.liquidwarsos.cloud.SnapshotItems.offset(wave,k)]==kind)slot=k;Assert.assertTrue("natural requested item",slot>=0);int at=com.xenris.liquidwarsos.cloud.SnapshotItems.offset(wave,slot);short[] x=IDLE.clone(),y=IDLE.clone();x[0]=(short)wave[at+1];y[0]=(short)wave[at+2];NativeInterface.setPlayerPosition(team,x,y);
    int[] got=null;for(int n=0;n<2000;n++){NativeInterface.stepDots();int[] state=NativeInterface.itemSnapshot();if(kind==7?state[147+team*10]==7:state[25+team*20+6]>0){got=state;break;}}Assert.assertNotNull("naturally devoured item",got);NativeInterface.setPlayerPosition(team,IDLE,IDLE);SystemClock.sleep(180);
    if(kind==7){ItemOverlay[] hud={null};Rect box=new Rect();scene.onActivity(a->{hud[0]=a.findViewById(R.id.item_overlay);hud[0].getGlobalVisibleRect(box);});float dp=context().getResources().getDisplayMetrics().density;tap(box.centerX(),box.bottom-44*dp);SystemClock.sleep(180);int target=(team+1)%6;while(got[13+target]<=0)target=(target+1)%6;String prefix=Util.teamToNameString(context(),target)+" ·";android.view.accessibility.AccessibilityNodeInfo root=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();android.view.accessibility.AccessibilityNodeInfo node=findText(root,prefix);Assert.assertNotNull("actual team choice button",node);Rect row=new Rect();node.getBoundsInScreen(row);int before=got[13+target],total=got[3];picture("controls177-death-target-dialog.jpg");tap(row.centerX(),row.centerY());apply(scene);NativeInterface.stepDots();int[] after=NativeInterface.itemSnapshot();Assert.assertEquals("selected enemy immediately zero",0,after[13+target]);Assert.assertEquals(total-before,after[3]);Assert.assertEquals(0,after[147+team*10]);SystemClock.sleep(160);picture("controls177-death-eliminated.jpg");records.put(new JSONObject().put("kind",7).put("seed",seed).put("target",target).put("before",before).put("after",after[13+target]).put("real_team_dialog_touch",true));
    }else{int buff=25+team*20+6;Assert.assertEquals(20000,got[buff]);picture("controls177-invincible-20s.jpg");int[] paused=NativeInterface.itemSnapshot();SystemClock.sleep(200);Assert.assertArrayEquals("pause does not use20s",paused,NativeInterface.itemSnapshot());for(int n=0;n<2857;n++)NativeInterface.stepDots();int[] end=NativeInterface.itemSnapshot();Assert.assertEquals(1,end[buff]);NativeInterface.stepDots();Assert.assertEquals(0,NativeInterface.itemSnapshot()[buff]);SystemClock.sleep(150);picture("controls177-invincible-expired.jpg");records.put(new JSONObject().put("kind",6).put("seed",seed).put("initial_ms",got[buff]).put("remaining_at19999",end[buff]).put("expired_at20006",true).put("paused_clock_stable",true));}
   }
  }write("controls177-natural-items.json",new JSONObject().put("status","PASS").put("real_cpp_core",true).put("natural_pickups_not_granted",true).put("controlled_steps_not_performance",true).put("models",0).put("records",records));
 }
 private static android.view.accessibility.AccessibilityNodeInfo findText(android.view.accessibility.AccessibilityNodeInfo n,String prefix){if(n==null)return null;if(n.getText()!=null&&n.getText().toString().startsWith(prefix))return n;for(int k=0;k<n.getChildCount();k++){android.view.accessibility.AccessibilityNodeInfo child=findText(n.getChild(k),prefix);if(child!=null)return child;}return null;}

 @Test public void healthAndDirectMinimapTeleport()throws Exception{
  Intent intent=prepare(1,101,100,true,false);StaticBits.team=1;
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] h={null};Rect bounds=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);h[0]=a.findViewById(R.id.item_overlay);h[0].getGlobalVisibleRect(bounds);});readyGL(gl[0],0);idle();
   for(int n=0;n<2000&&NativeInterface.itemSnapshot()[2]==0;n++)NativeInterface.stepDots();int[] wave=NativeInterface.itemSnapshot();int slot=-1;for(int k=0;k<SnapshotItems.slots(wave);k++)if(wave[SnapshotItems.offset(wave,k)]==3)slot=k;Assert.assertTrue("natural teleport fixture",slot>=0);int at=SnapshotItems.offset(wave,slot),x=wave[at+1],y=wave[at+2];short[] tx=IDLE.clone(),ty=IDLE.clone();tx[0]=(short)x;ty[0]=(short)y;NativeInterface.setPlayerPosition(1,tx,ty);
   int[] contact=null;for(int n=0;n<1400;n++){NativeInterface.stepDots();int[] now=NativeInterface.itemSnapshot();if(SnapshotItems.hp(now,slot)<1200){contact=now;break;}}
   Assert.assertNotNull("contact reached",contact);Assert.assertEquals(3,contact[SnapshotItems.offset(contact,slot)]);Assert.assertEquals(0,contact[157]);Assert.assertTrue(SnapshotItems.hp(contact,slot)>=1196);int[] actualDots=NativeInterface.modelSnapshot();for(int q=com.xenris.liquidwarsos.cloud.ModelWorld.HEADER;q<actualDots.length;q++){int px=actualDots[q]&2047,py=actualDots[q]>>>11&1023;for(int k=0;k<SnapshotItems.slots(contact);k++){int offset=SnapshotItems.offset(contact,k);if(contact[offset]<0)continue;int hp=SnapshotItems.hp(contact,k),r=8;for(int rr=2;rr<8;rr++)if(hp*64<=1200*rr*rr){r=rr;break;}int dx=px-contact[offset+1],dy=py-contact[offset+2];Assert.assertTrue("real particles cannot overlap solid item",dx*dx+dy*dy>r*r);}}SystemClock.sleep(150);picture("controls177-item-first-contact.jpg");
   for(int n=0;n<150;n++){NativeInterface.stepDots();SystemClock.sleep(7);}int[] middle=NativeInterface.itemSnapshot();Assert.assertEquals(3,middle[SnapshotItems.offset(middle,slot)]);Assert.assertTrue(SnapshotItems.hp(middle,slot)>0&&SnapshotItems.hp(middle,slot)<1200);SystemClock.sleep(160);picture("controls177-item-half-hp.jpg");int[] held=NativeInterface.itemSnapshot();SystemClock.sleep(180);Assert.assertArrayEquals("paused HP does not tick",held,NativeInterface.itemSnapshot());
   for(int n=0;n<1500&&NativeInterface.itemSnapshot()[157]!=3;n++)NativeInterface.stepDots();Assert.assertEquals(3,NativeInterface.itemSnapshot()[157]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("controls177-minimap-teleport-ready.jpg");Assert.assertFalse((Boolean)get(h[0],"aiming"));
   byte[] wall=NativeInterface.modelTerrain();int wx=-1,wy=-1,fx=-1,fy=-1;for(int yy=20;yy<460;yy+=8)for(int xx=25;xx<775;xx+=8){boolean rock=true,floor=true;for(int dy=-3;dy<=3;dy++)for(int dx=-3;dx<=3;dx++){rock&=wall[(yy+dy)*800+xx+dx]!=0;floor&=wall[(yy+dy)*800+xx+dx]==0;}if(rock&&wx<0){wx=xx;wy=yy;}if(floor&&xx>450&&fx<0){fx=xx;fy=yy;}}Assert.assertTrue(wx>=0&&fx>=0);
   miniTap(h[0],bounds,wx,wy,true);apply(scene);NativeInterface.stepDots();Assert.assertEquals("wall keeps teleport",3,NativeInterface.itemSnapshot()[157]);SystemClock.sleep(180);picture("controls177-minimap-wall-rejected.jpg");
   int armyBefore=NativeInterface.itemSnapshot()[14];miniTap(h[0],bounds,fx,fy,true);short[][] selected=targets(scene);Assert.assertEquals(-3,selected[0][4]);Assert.assertEquals(fx,selected[0][3]);Assert.assertEquals(fy,selected[1][3]);apply(scene);NativeInterface.stepDots();int[] done=NativeInterface.itemSnapshot();Assert.assertEquals(0,done[157]);Assert.assertEquals(armyBefore,done[11]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("controls177-minimap-teleported.jpg");Assert.assertTrue(((Integer)get(h[0],"lastCameraTeleport"))>0);
   long before=gl[0].framesDrawn();scene.onActivity(a->{gl[0].onPause();gl[0].onResume();});long deadline=SystemClock.uptimeMillis()+5000;while(gl[0].framesDrawn()<=before&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(30);Assert.assertTrue(gl[0].framesDrawn()>before);Assert.assertArrayEquals(done,NativeInterface.itemSnapshot());
   write("controls177-health-teleport.json",new JSONObject().put("status","PASS").put("natural_pickup",true).put("first_contact_hp",SnapshotItems.hp(contact,slot)).put("middle_hp",SnapshotItems.hp(middle,slot)).put("paused_hp_stable",true).put("no_bottom_card_required",true).put("wall_rejected_retained",true).put("selected_xy",new JSONArray().put(fx).put(fy)).put("teleported",armyBefore).put("egl_stable",true).put("models",0).put("controlled_native_steps",true));
  }
 }

